import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s2-u02")
C = "A1-A2"

L(1, "Horas certas e meias horas", "Het is drie uur. Het is half vier (= 3h30!).",
  ["Dizer horas certas e meias horas", "Perceber que «half vier» é 3h30"],
  vocab=[V("v-half","half","meia (hora)","adjective",note="half vier = 3h30 (meia hora antes das quatro)."), V("v-precies","precies","exatamente|em ponto","adverb"),
         V("v-middag","middag","tarde|meio-dia","noun","de",note="'s middags = à tarde; om twaalf uur 's middags = ao meio-dia."),
         V("v-ongeveer","ongeveer","mais ou menos|cerca de","adverb")],
  ex=[("Het is drie uur.","São três horas."),("Het is half vier.","São três e meia.","Meia hora ANTES das quatro."),("Het is precies twaalf uur.","É meio-dia em ponto.")],
  gram=[G("g-half","«Half» olha para a hora seguinte","Em neerlandês a meia hora diz-se em relação à **hora seguinte**: **half vier** = 3h30 (metade do caminho até às 4). **half acht** = 7h30. Para horas certas: **drie uur**. Na fala usa-se o relógio de 12 horas; o de 24 horas aparece em horários e documentos.",
    [("half negen","8h30"),("half één","12h30")],
    "Um português ouve «half vier» e pensa em 4h30 — é o erro mais comum. Pense «meia para as quatro».")],
  review=["v-hoe-laat","v-uur","v-om"],
  cefr=C, exs=[
    MC("«Het is half vier.» Que horas são?", ["*3h30","4h30|«half vier» = meia hora antes das quatro.","4h00|Seria «vier uur»."], "half + hora seguinte.", ["v-half"]),
    MC("Como se diz 7h30?", ["*half acht","half zeven|«half zeven» = 6h30.","zeven half|A ordem é «half» + hora seguinte."], "7h30 = half acht.", ["v-half"]),
    TR("pt-nl","São cinco horas.", ["Het is vijf uur"], "Hora certa: … uur.", ["v-uur"]),
    TR("pt-nl","São nove e meia.", ["Het is half tien"], "9h30 = half tien.", ["v-half"]),
    TR("nl-pt","Het is half één.", ["É meio-dia e meia","É meia-noite e meia","São 12h30"], "half één = 12h30.", ["v-half"]),
    LI("Het is half twee.", ["Het is half twee","1:30","13:30"], "É uma e meia.", "half twee = 1h30.", ["v-half"]),
    MA([("half vier","3h30"),("vier uur","4h00"),("half vijf","4h30"),("vijf uur","5h00")], "Horas e meias.", ["v-half","v-uur"]),
    FE(["De","trein","komt","om","half","acht,","dus","om","acht","uur","dertig."], 8, "zeven", "half acht = 7h30, ou seja «zeven uur dertig».", ["v-half"]),
    FB("Hoe laat is het? — Het is ___ zes uur.", ["precies","ongeveer"], "precies = em ponto.", ["v-precies"], choices=["precies","half uur","laat"], tr="Que horas são? — São seis em ponto."),
    DL([("Tom","Hoe laat begint de film?","A que horas começa o filme?"),("Eva","")], ["*Om half negen.","Half negen uur.|Com «half» não se diz «uur».","Ja, om negen.|«Ja» não responde a «hoe laat»."], "Om half negen = às 8h30.", ["v-half"]),
  ], diff=2, mins=5)

L(2, "Um quarto: kwart over e kwart voor", "Het is kwart over drie (3h15), kwart voor vier (3h45).",
  ["Dizer horas com um quarto"],
  vocab=[V("v-kwart","kwart","quarto (de hora)","noun","het"), V("v-over","over","depois de|e (horas)","preposition",note="kwart over drie = 3h15"),
         V("v-voor","voor","antes de|menos (horas)|para","preposition",note="kwart voor vier = 3h45")],
  ex=[("Het is kwart over drie.","São três e um quarto."),("Het is kwart voor vier.","São quatro menos um quarto."),("Om kwart over negen begint de les.","A aula começa às nove e um quarto.")],
  gram=[G("g-kwart","Kwart over / kwart voor","**kwart over** + hora = hora + 15 minutos (*kwart over drie* = 3h15). **kwart voor** + hora = hora − 15 minutos (*kwart voor vier* = 3h45). Tal como em português: «e um quarto» / «menos um quarto».",
    [("kwart over twaalf","12h15"),("kwart voor acht","7h45")])],
  review=["v-half","v-hoe-laat","v-om"],
  cefr=C, exs=[
    MC("«kwart over drie» =", ["*3h15","2h45|Isso é «kwart voor drie».","3h45|Isso é «kwart voor vier»."], "over = depois.", ["v-kwart","v-over"]),
    MC("«kwart voor vier» =", ["*3h45","4h15|Isso é «kwart over vier».","4h45|Isso é «kwart voor vijf»."], "voor = antes.", ["v-kwart","v-voor"]),
    TR("pt-nl","São oito e um quarto.", ["Het is kwart over acht"], "kwart over acht.", ["v-kwart","v-over"]),
    TR("pt-nl","São dez menos um quarto.", ["Het is kwart voor tien"], "kwart voor tien.", ["v-kwart","v-voor"]),
    MA([("kwart over twee","2h15"),("half drie","2h30"),("kwart voor drie","2h45"),("drie uur","3h00")], "Uma hora em quartos.", ["v-kwart","v-half"]),
    LI("Het is kwart voor zeven.", ["Het is kwart voor zeven","6:45","18:45"], "São sete menos um quarto.", "kwart voor zeven = 6h45.", ["v-kwart","v-voor"]),
    FB("De trein vertrekt om kwart ___ elf (10h45).", ["voor"], "10h45 = kwart voor elf.", ["v-voor"], choices=["voor","over","half"], tr="O comboio parte às 10h45."),
    FE(["Het","is","kwart","na","drie."], 3, "over", "Diz-se «kwart over drie».", ["v-over"]),
    TR("nl-pt","De les begint om kwart over negen.", ["A aula começa às nove e um quarto","A aula começa às 9h15"], "kwart over negen = 9h15.", ["v-kwart"]),
    WO("O jantar é às sete menos um quarto.", ["We","eten","om","kwart","voor","zeven"], "om kwart voor zeven.", ["v-kwart","v-voor"]),
  ], diff=2, mins=5)

L(3, "Minutos: tien voor half vier", "O sistema completo: minutos em relação à hora e à meia hora.",
  ["Dizer qualquer hora com minutos"],
  vocab=[V("v-minuut","minuut","minuto","noun","de","minuten"), V("v-klok-kijken","klokkijken","ver as horas","verb",note="Kun je klokkijken? = Sabes ver as horas?")],
  ex=[("tien over drie","3h10"),("tien voor half vier","3h20","10 minutos antes das 3h30."),("vijf over half vier","3h35","5 minutos depois das 3h30."),("tien voor vier","3h50")],
  gram=[G("g-minutos","Minutos à volta da meia hora","Até aos 15 minutos conta-se a partir da hora: **tien over drie** (3h10). Entre os 15 e os 45, conta-se a partir da **meia hora**: **tien voor half vier** (3h20), **vijf over half vier** (3h35). Depois dos 45, conta-se para a hora seguinte: **tien voor vier** (3h50).",
    [("vijf voor half negen","8h25"),("tien over half negen","8h40")],
    "Parece complicado, mas é sistemático: os pontos de referência são a hora, a meia hora e a hora seguinte. Em horários escritos usa-se 15:20.")],
  review=["v-half","v-kwart","v-over","v-voor"],
  cefr=C, exs=[
    MC("«tien voor half vier» =", ["*3h20","3h50|Isso é «tien voor vier».","4h20|A referência é «half vier» = 3h30."], "3h30 − 10 min = 3h20.", ["v-half","v-voor"]),
    MC("«vijf over half vier» =", ["*3h35","4h35|«half vier» = 3h30.","3h05|Isso é «vijf over drie»."], "3h30 + 5 min = 3h35.", ["v-half","v-over"]),
    MC("Como se diz 3h10?", ["*tien over drie","tien voor half drie|Isso seria 2h20.","drie uur tien|Na fala usa-se «tien over drie»."], "Até 15 minutos: … over + hora.", ["v-over"]),
    MA([("tien over vijf","5h10"),("tien voor half zes","5h20"),("tien over half zes","5h40"),("tien voor zes","5h50")], "Uma hora em minutos.", ["v-over","v-voor","v-half"]),
    TR("pt-nl","São oito e vinte e cinco.", ["Het is vijf voor half negen"], "8h30 − 5 = vijf voor half negen.", ["v-half","v-voor"]),
    LI("Het is tien over half twee.", ["Het is tien over half twee","1:40","13:40"], "É uma e quarenta.", "half twee (1h30) + 10.", ["v-half","v-over"]),
    FB("De bus komt om vijf ___ half zeven (6h25).", ["voor"], "6h30 − 5 = vijf voor half zeven.", ["v-voor"], choices=["voor","over","na"], tr="O autocarro chega às 6h25."),
    AR("minuut","o minuto","de", "«De minuut» — plural «minuten».", ["v-minuut"]),
    TR("nl-pt","Over vijf minuten.", ["Daqui a cinco minutos","Dentro de cinco minutos"], "over + tempo = daqui a.", ["v-minuut","v-over"]),
    TR("pt-nl","São quatro e cinco.", ["Het is vijf over vier"], "Até 15 minutos: … over + hora.", ["v-over"]),
  ], diff=3, mins=6)

L(4, "A horas, cedo, atrasado", "Pontualidade — muito valorizada nos Países Baixos.",
  ["Dizer se está a horas ou atrasado", "Pedir desculpa pelo atraso"],
  vocab=[V("v-op-tijd","op tijd","a horas","expression"), V("v-te-laat","te laat","atrasado|tarde demais","expression"),
         V("v-vroeg","vroeg","cedo","adjective"), V("v-later","later","mais tarde","adverb"), V("v-vertraging","vertraging","atraso","noun","de",note="De trein heeft vertraging = o comboio está atrasado.")],
  ex=[("Ik ben op tijd.","Estou a horas."),("Sorry, ik ben te laat!","Desculpa, cheguei atrasado!"),("De trein heeft tien minuten vertraging.","O comboio tem dez minutos de atraso.")],
  gram=[G("g-pontualidade","Pontualidade","Nos Países Baixos a **pontualidade** é levada a sério, sobretudo no trabalho e em consultas. Se vai chegar atrasado, é educado avisar: *Ik ben vijf minuten later* (chego cinco minutos mais tarde).",
    [("Ik kom iets later.","Chego um pouco mais tarde.")],
    "Uma tolerância de 10–15 minutos, comum em Portugal em contextos informais, pode ser vista como falta de respeito.")],
  review=["v-laat","v-minuut","v-trein","v-sorry"],
  cefr=C, exs=[
    MA([("op tijd","a horas"),("te laat","atrasado"),("vroeg","cedo"),("later","mais tarde"),("vertraging","atraso")], "Pontualidade.", ["v-op-tijd","v-te-laat","v-vroeg","v-later","v-vertraging"]),
    TR("pt-nl","Desculpa, estou atrasado!", ["Sorry(,) ik ben te laat"], "te laat zijn.", ["v-te-laat"]),
    TR("nl-pt","De trein heeft vertraging.", ["O comboio está atrasado","O comboio tem atraso"], "vertraging hebben = ter atraso.", ["v-vertraging"]),
    MC("Vai chegar 10 minutos atrasado a uma reunião. O que faz?", ["*Envia uma mensagem: «Ik ben tien minuten later.»","Não diz nada: é normal.|Nos Países Baixos é educado avisar.","Diz só «Doei!»|Não explica nada."], "Avisar é a norma.", ["v-later"]),
    FB("Ik sta altijd ___ op: om zes uur.", ["vroeg"], "vroeg = cedo.", ["v-vroeg"], choices=["vroeg","laat","op tijd"], tr="Levanto-me sempre cedo: às seis."),
    AR("vertraging","o atraso","de", "-ing → de.", ["v-vertraging"]),
    LI("Gelukkig ben je op tijd!", ["Gelukkig ben je op tijd"], "Ainda bem que chegaste a horas!", "gelukkig = felizmente.", ["v-op-tijd"]),
    FE(["Ik","ben","laat","te."], 2, "te laat", "A ordem é «te laat».", ["v-te-laat"]),
    DL([("Chefe","Je bent te laat!","Estás atrasado!"),("Pedro","")], ["*Sorry, de trein had vertraging.","Graag gedaan!|Não faz sentido.","Ik ben vroeg.|Contradiz a situação."], "Pedir desculpa e explicar.", ["v-vertraging"]),
    CO("text","Mensagem da Eva", "Hoi Sanne! Sorry, ik ben iets later. De bus heeft vertraging. Ik ben er om kwart over acht in plaats van om acht uur. Tot zo!",
       [("Porque se atrasa a Eva?", ["*O autocarro está atrasado","Acordou tarde","Está doente"]),("A que horas chega?", ["*Às 8h15","Às 8h00","Às 7h45"])],
       "in plaats van = em vez de; tot zo = até já.", ["v-later","v-vertraging","v-kwart"]),
  ], diff=2, mins=6)

